{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause Ordinance (JCO)","requirement":"A landlord may not terminate a tenancy without just cause and must pay relocation assistance for no-fault evictions. Eviction notices must be filed with LAHD within three business days, and no eviction for nonpayment unless rent owed exceeds Fair Market Rent.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles not regulated by the City's Rent Stabilization Ordinance. Applies once the tenant has lived in the unit six months or their original lease expired. Can apply to buildings newer than October 1, 1978 and to single-family dwellings.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exemptions include owner's roommate and HACLA/government-owned properties."},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term treatment centers for substance abuse, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"Covers units not regulated by the City's Rent Stabilization Ordinance (RSO).","confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act of 2019 (AB 1482) annual rent cap","requirement":"Annual rent increases are capped at 5% plus the regional cost-of-living change, or 10%, whichever is lower. The maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025, and 8.8% the year before.","key_value":"5% + CPI, max 10%; 8.9% (2024-08-01 to 2025-07-31)","coverage_conditions":"Buildings older than 15 years, on a rolling basis. Excludes units built in the last 15 years, deed-restricted affordable units, certain dormitories, and owner-occupied two-unit properties; single-family homes and condominiums only with ownership and written-notice conditions.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"15-year rolling cutoff measured from construction date"},"exemptions":"Units constructed within the last 15 years, units restricted by deed or regulatory document limiting affordability to low or moderate-income households, certain dormitories, owner-occupied two-unit properties, single-family homes and condominiums meeting the ownership and written-notice conditions, and units already subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"State cap; the City's JCO does not regulate rent increases, and units subject to the City's RSO are exempt from AB 1482.","confidence":0.75,"conflict_flag":false,"conflict_note":null}
